use vstd::prelude::*;

verus! {
    // sum takes two equally‐sized vectors a and b of u32s (length ≤ 100),
    // with the guarantee that for each index i, a[i] + b[i] < 1000.
    // It returns a new vector c of the same length, where
    // c[i] = a[i] + b[i] for all valid i.
    fn sum(a: &Vec<u32>, b: &Vec<u32>) -> (c: Vec<u32>)
        requires
            a.len() == b.len(),
            a.len() <= 100,
            // For every index i in bounds, the sum is < 1000
            forall |i: usize| i < a.len() ==> a[i] + b[i] < 1000,
        ensures
            c.len() == a.len(),
            forall |i: usize| i < c.len() ==> c[i] == a[i] + b[i],
    {
        let n = a.len();
        let mut c: Vec<u32> = Vec::with_capacity(n);
        let mut i: usize = 0;
        // We'll iterate i = 0..n, maintaining that
        //  * c.len() == i
        //  * for all j < i, c[j] == a[j] + b[j]
        while i < n
            invariant
                i <= n,
                c.len() == i,
                forall |j: usize| j < i ==> c[j] == a[j] + b[j],
            decreases n - i,
        {
            let ai = a[i];
            let bi = b[i];
            // By precondition, ai + bi < 1000 < 2^32, so this addition cannot overflow.
            assert(ai + bi < 1000);
            c.push(ai + bi);
            i = i + 1;
        }
        c
    }
}

